interface SchemaErrorObject {
  keyword: string;
  instancePath?: string;
  dataPath?: string;
  params: Record<string, unknown>;
  message?: string;
}

type AjvConstructor = new (options: Record<string, unknown>) => {
  compile: (schema: Record<string, unknown>) => ValidateFunction;
};

const Ajv = (typeof AjvModule === 'function'
  ? AjvModule
  : (AjvModule as {default: unknown}).default) as AjvConstructor;
const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
const schemaValidators = new WeakMap<Record<string, unknown>, ValidateFunction>();

function compileSchema(toolName: string, schema: Record<string, unknown>): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${(error as Error).message}`, {cause: error});
  }
}

function formatValidationErrors(errors: ErrorObject[]): string[] {
  return (errors as SchemaErrorObject[]).map(formatValidationError);
}

function formatValidationError(error: SchemaErrorObject): string {
  const rawPath = error.instancePath ?? error.dataPath ?? '';
  const trimmedPath = rawPath.slice(1);
  const path = trimmedPath.replace(/\//g, '.');
  if (error.keyword === 'required') {
    const {missingProperty} = error.params as {missingProperty: string};
    const fullPath = path ? `${path}.${missingProperty}` : missingProperty;
    return `missing required property "${fullPath}"`;
  }
  const target = path || 'input';
  return `${target} ${error.message}`;
}

