it('rejects input missing a required field with a ToolResponse and never invokes the executor', async () => {
  const registry = new ToolRegistry();
  const invokedWith: Array<Record<string, unknown>> = [];
  const schema = {
    type: 'object',
    properties: {
      location: {type: 'string'},
      coords: {type: 'object', properties: {lat: {type: 'number'}}, required: ['lat']},
    },
    required: ['location'],
  };
  registry.register({name: 'fetch_forecast', description: 'Forecast', inputSchema: schema}, async input => {
    invokedWith.push(input);
    return 'clear';
  });

  const {result} = await registry.execute('fetch_forecast', {coords: {}});

  expect({
    invokedWith,
    mentionsLocation: result.includes('location'),
    mentionsNestedLat: result.includes('coords.lat'),
    mentionsRequired: /required/i.test(result),
  }).toEqual({
    invokedWith: [],
    mentionsLocation: true,
    mentionsNestedLat: true,
    mentionsRequired: true,
  });
});

